mapper.select:
SELECT t.club_id, c.club_name, COUNT(1) AS activity_count, COALESCE(SUM(t.registration_count), 0) AS registration_count, COALESCE(SUM(t.sign_in_count), 0) AS sign_in_count, COALESCE(SUM(t.current_participants), 0) AS total_participants FROM ( SELECT a.id, a.club_id, COALESCE(a.current_participants, 0) AS current_participants, ( SELECT COUNT(1) FROM registrations r WHERE r.activity_id = a.id AND r.status = 1
AND r.registration_time >= #{startTime}
AND r.registration_time <= #{endTime}
) AS registration_count, ( SELECT COUNT(1) FROM sign_ins s WHERE s.activity_id = a.id
AND s.sign_in_time >= #{startTime}
AND s.sign_in_time <= #{endTime}
) AS sign_in_count FROM activities a WHERE 1 = 1
AND a.club_id = #{clubId}
AND a.start_time >= #{startTime}
AND a.start_time <= #{endTime}
) t JOIN clubs c ON c.id = t.club_id GROUP BY t.club_id, c.club_name ORDER BY activity_count DESC, registration_count DESC

SELECT period, COUNT(1) AS activity_count, COALESCE(SUM(registration_count), 0) AS registration_count, COALESCE(SUM(sign_in_count), 0) AS sign_in_count FROM ( SELECT CASE WHEN #{granularity} = 'MONTH' THEN DATE_FORMAT(a.start_time, '%Y-%m') WHEN #{granularity} = 'WEEK' THEN DATE_FORMAT(a.start_time, '%x-W%v') ELSE DATE_FORMAT(a.start_time, '%Y-%m-%d') END AS period, ( SELECT COUNT(1) FROM registrations r WHERE r.activity_id = a.id AND r.status = 1
AND r.registration_time >= #{startTime}
AND r.registration_time <= #{endTime}
) AS registration_count, ( SELECT COUNT(1) FROM sign_ins s WHERE s.activity_id = a.id
AND s.sign_in_time >= #{startTime}
AND s.sign_in_time <= #{endTime}
) AS sign_in_count FROM activities a WHERE 1 = 1
AND a.club_id = #{clubId}
AND a.start_time >= #{startTime}
AND a.start_time <= #{endTime}
) t GROUP BY period ORDER BY period ASC

SELECT u.id AS user_id, u.username, u.real_name, COUNT(DISTINCT r.activity_id) AS registration_count, COALESCE(SUM(s.sign_in_count), 0) AS sign_in_count, CASE WHEN COUNT(DISTINCT r.activity_id) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(s.sign_in_count), 0) / COUNT(DISTINCT r.activity_id), 4) END AS participation_rate FROM registrations r JOIN users u ON u.id = r.user_id JOIN activities a ON a.id = r.activity_id LEFT JOIN ( SELECT activity_id, user_id, COUNT(1) AS sign_in_count FROM sign_ins WHERE 1 = 1
AND sign_in_time >= #{startTime}
AND sign_in_time <= #{endTime}
GROUP BY activity_id, user_id ) s ON s.activity_id = r.activity_id AND s.user_id = r.user_id WHERE r.status = 1
AND a.club_id = #{clubId}
AND r.registration_time >= #{startTime}
AND r.registration_time <= #{endTime}
GROUP BY u.id, u.username, u.real_name ORDER BY registration_count DESC, sign_in_count DESC
LIMIT #{limit}

SELECT u.id AS user_id, u.username, u.real_name, COALESCE(COUNT(DISTINCT r.activity_id), 0) AS registration_count, COALESCE(SUM(s.sign_in_count), 0) AS sign_in_count, CASE WHEN COALESCE(COUNT(DISTINCT r.activity_id), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(s.sign_in_count), 0) / COUNT(DISTINCT r.activity_id), 4) END AS participation_rate FROM users u LEFT JOIN registrations r ON r.user_id = u.id AND r.status = 1 LEFT JOIN activities a ON a.id = r.activity_id LEFT JOIN ( SELECT activity_id, user_id, COUNT(1) AS sign_in_count FROM sign_ins WHERE 1 = 1
AND sign_in_time >= #{startTime}
AND sign_in_time <= #{endTime}
GROUP BY activity_id, user_id ) s ON s.activity_id = r.activity_id AND s.user_id = u.id WHERE u.id = #{userId}
AND (a.club_id = #{clubId} OR a.club_id IS NULL)
AND (r.registration_time IS NULL OR r.registration_time >= #{startTime})
AND (r.registration_time IS NULL OR r.registration_time <= #{endTime})
GROUP BY u.id, u.username, u.real_name
